use std::rc::Rc;
use std::sync::Arc;

struct Data {
    value: i32,
}

impl Data {
    fn new(v: i32) -> Self {
        Data { value: v }
    }
}

fn main() {
    // Create 5 synthetic structs with varying lifetimes (simulated via stack allocation)
    let a = Data::new(1);
    let b = Data::new(2);
    let c = Data::new(3);
    let d = Data::new(4);
    let e = Data::new(5);

    // Clone into Rc
    let rc_a = Rc::new(a);
    let rc_b = Rc::new(b);
    let rc_c = Rc::new(c);
    let rc_d = Rc::new(d);
    let rc_e = Rc::new(e);

    // Move into Arc
    let arc_a = Arc::new(Rc::clone(&rc_a));
    let arc_b = Arc::new(Rc::clone(&rc_b));
    let arc_c = Arc::new(Rc::clone(&rc_c));
    let arc_d = Arc::new(Rc::clone(&rc_d));
    let arc_e = Arc::new(Rc::clone(&rc_e));

    // Explicit Drop calls on original Rc clones
    drop(rc_a);
    drop(rc_b);
    drop(rc_c);
    drop(rc_d);
    drop(rc_e);

    // Assert reference counts match expected values after drops
    // Each Arc holds one Rc, so after dropping the original Rc clones,
    // the reference count for each should be 1 (held by the Arc itself).
    assert_eq!(Arc::strong_count(&arc_a), 1);
    assert_eq!(Arc::strong_count(&arc_b), 1);
    assert_eq!(Arc::strong_count(&arc_c), 1);
    assert_eq!(Arc::strong_count(&arc_d), 1);
    assert_eq!(Arc::strong_count(&arc_e), 1);

    println!("success");
}
